GRANT EXECUTE ON FUNCTION public.is_community_moderator() TO anon;
CREATE POLICY "hide moderated posts" ON public.posts AS RESTRICTIVE FOR SELECT TO anon,authenticated USING(NOT EXISTS(SELECT 1 FROM public.community_hidden h WHERE h.target_kind='post' AND h.target_id=posts.id) OR author_id=auth.uid() OR public.is_community_moderator());
CREATE POLICY "hide moderated comments" ON public.comments AS RESTRICTIVE FOR SELECT TO anon,authenticated USING((NOT EXISTS(SELECT 1 FROM public.community_hidden h WHERE h.target_kind='comment' AND h.target_id=comments.id) AND NOT EXISTS(SELECT 1 FROM public.community_hidden h WHERE h.target_kind='post' AND h.target_id=comments.post_id)) OR author_id=auth.uid() OR public.is_community_moderator());
CREATE POLICY "hide moderated polls" ON public.polls AS RESTRICTIVE FOR SELECT TO anon,authenticated USING(NOT EXISTS(SELECT 1 FROM public.community_hidden h WHERE h.target_kind='poll' AND h.target_id=polls.id) OR public.is_community_moderator());
CREATE FUNCTION public.validate_community_report() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (NEW.target_kind='post' AND NOT EXISTS(SELECT 1 FROM public.posts WHERE id=NEW.target_id)) OR (NEW.target_kind='comment' AND NOT EXISTS(SELECT 1 FROM public.comments WHERE id=NEW.target_id)) OR (NEW.target_kind='poll' AND NOT EXISTS(SELECT 1 FROM public.polls WHERE id=NEW.target_id)) THEN RAISE EXCEPTION 'Content is unavailable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_report_target BEFORE INSERT ON public.community_reports FOR EACH ROW EXECUTE FUNCTION public.validate_community_report();